import{_ as t,o,c as n,ah as r}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse(`{"title":"Screenplay Update: Scene 15 - The Protocol of Silence","description":"A meeting between Helmut Horten and Siegfried Alsberg in 1933. The cold reality of 'Market Correction'.","frontmatter":{"title":"Screenplay Update: Scene 15 - The Protocol of Silence","description":"A meeting between Helmut Horten and Siegfried Alsberg in 1933. The cold reality of 'Market Correction'.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/szene-das-protokoll-des-schweigens.md","filePath":"en/logbuch/szene-das-protokoll-des-schweigens.md"}`),s={name:"en/logbuch/szene-das-protokoll-des-schweigens.md"};function a(i,e,l,c,h,d){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="screenplay-update-scene-15-the-protocol-of-silence" tabindex="-1">Screenplay Update: Scene 15 - The Protocol of Silence <a class="header-anchor" href="#screenplay-update-scene-15-the-protocol-of-silence" aria-label="Permalink to &quot;Screenplay Update: Scene 15 - The Protocol of Silence&quot;">​</a></h1><p><strong>STYLE:</strong> Cold, almost clinical. High contrasts. The room feels sterile, despite the heavy oak furniture. One only hears the ticking of a wall clock and the scratching of a nib on paper.</p><p><strong>CAST:</strong></p><ul><li><strong>Helmut Horten:</strong> August Diehl (young, extremely controlled, almost immobile)</li><li><strong>Siegfried Alsberg:</strong> An older actor who radiates dignity but is marked by exhaustion and fear.</li></ul><hr><p><strong>INT. ALSBERG&#39;S OFFICE - DAY (1933)</strong></p><p>Siegfried Alsberg stands at the window and looks down at the street. One can hear muffled marching music and shouts from outside. Helmut Horten (Diehl) sits at the desk – <em>his</em> new desk. He flips through a stack of documents.</p><p><strong>ALSBERG</strong> (without turning around) My father built this house. He knew every stone, every employee by name. Do you know what that means, Mr. Horten?</p><p>Horten does not answer immediately. He sets a document aside and smooths it with the back of his hand.</p><p><strong>HORTEN</strong> (calmly) It means that you are emotionally attached to an object that the market has already given up on. Stones have no memory, Mr. Alsberg. And names... names are very easily replaced in payroll lists.</p><p>Alsberg turns around slowly. His hands tremble slightly.</p><p><strong>ALSBERG</strong> The price you are offering... that is not a price. That is an insult. It doesn&#39;t even cover the loans that your friends at the bank have suddenly called in.</p><p><strong>HORTEN</strong> (looks at him directly, his gaze is empty) I don&#39;t set the prices, I only read them. The situation out there... (he points vaguely towards the window) ...is the price. I&#39;m offering you a solution. A clean separation. You sign here, and you can leave. Without noise. Without... complications.</p><p><strong>ALSBERG</strong> (bitterly) &quot;Market correction&quot;. That&#39;s your word for it, isn&#39;t it?</p><p><strong>HORTEN</strong> It&#39;s a technical term. Efficiency isn&#39;t cruel, Mr. Alsberg. It&#39;s only consistent. The universe prefers a vacuum, and in German trade, there is currently a lot of it. I am merely filling it.</p><p>Horten pushes the fountain pen across the desk. It shines in the pale light.</p><p><strong>HORTEN</strong> Sign the protocol. It is an act of reason. For you, it is the end of an era. For me... it is the first square meter.</p><p>Alsberg stares at the pen as if it were a weapon. The ticking of the clock gets louder.</p><p><strong>FADE TO BLACK.</strong></p>',19)])])}const u=t(s,[["render",a]]);export{g as __pageData,u as default};
